import { useState, useEffect, useCallback } from 'react';
import type { SavedItem, BioState, BotLog } from './lib/api';
import { api } from './lib/api';
import SavedItems from './components/SavedItems';
import BioStatus from './components/BioStatus';
import LogViewer from './components/LogViewer';

type Tab = 'saves' | 'bio' | 'logs';

export default function App() {
  const [tab, setTab] = useState<Tab>('saves');
  const [saves, setSaves] = useState<SavedItem[]>([]);
  const [savesTotal, setSavesTotal] = useState(0);
  const [bio, setBio] = useState<BioState | null>(null);
  const [logs, setLogs] = useState<BotLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [savesRes, bioRes, logsRes] = await Promise.all([
        api.saves(),
        api.bio(),
        api.logs(),
      ]);
      setSaves(savesRes.items);
      setSavesTotal(savesRes.total);
      setBio(bioRes);
      setLogs(logsRes.logs);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to load data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
    const interval = setInterval(load, 30_000);
    return () => clearInterval(interval);
  }, [load]);

  const tabs: { id: Tab; label: string; count?: number }[] = [
    { id: 'saves', label: 'Saves', count: savesTotal },
    { id: 'bio', label: 'Bio Engine' },
    { id: 'logs', label: 'Logs', count: logs.length },
  ];

  return (
    <div className="min-h-screen bg-surface text-on-surface font-sans">
      <header className="border-b border-outline-variant bg-surface-container sticky top-0 z-10">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-primary flex items-center justify-center text-on-primary text-sm font-bold">
              L
            </div>
            <div>
              <h1 className="text-base font-semibold tracking-tight text-on-surface">LifeOS</h1>
              <p className="text-xs text-on-surface-variant">Telegram Self-Bot Dashboard</p>
            </div>
          </div>
          <button
            onClick={load}
            className="text-xs text-primary hover:text-primary/80 transition-colors px-3 py-1.5 rounded-full border border-primary/30 hover:bg-primary/10"
          >
            {loading ? 'Syncing…' : 'Refresh'}
          </button>
        </div>

        <div className="max-w-5xl mx-auto px-4 sm:px-6 flex gap-1 pb-0">
          {tabs.map(t => (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className={`px-4 py-2.5 text-sm font-medium border-b-2 transition-colors ${
                tab === t.id
                  ? 'border-primary text-primary'
                  : 'border-transparent text-on-surface-variant hover:text-on-surface'
              }`}
            >
              {t.label}
              {t.count !== undefined && (
                <span className={`ml-1.5 text-xs px-1.5 py-0.5 rounded-full ${
                  tab === t.id ? 'bg-primary/20 text-primary' : 'bg-surface-variant text-on-surface-variant'
                }`}>
                  {t.count}
                </span>
              )}
            </button>
          ))}
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 sm:px-6 py-6">
        {error && (
          <div className="mb-4 px-4 py-3 rounded-xl bg-error/10 border border-error/30 text-error text-sm">
            {error}
          </div>
        )}

        {loading && !saves.length && !bio && !logs.length ? (
          <div className="flex items-center justify-center h-64 text-on-surface-variant text-sm">
            Loading…
          </div>
        ) : (
          <>
            {tab === 'saves' && <SavedItems items={saves} total={savesTotal} />}
            {tab === 'bio' && <BioStatus state={bio} />}
            {tab === 'logs' && <LogViewer logs={logs} />}
          </>
        )}
      </main>
    </div>
  );
}

import type { BioState } from '../lib/api';

interface Props {
  state: BioState | null;
}

function Field({ label, value, mono = false }: { label: string; value: string; mono?: boolean }) {
  return (
    <div className="flex flex-col gap-0.5">
      <span className="text-xs text-on-surface-variant uppercase tracking-widest opacity-60">{label}</span>
      <span className={`text-sm text-on-surface ${mono ? 'font-mono' : ''}`}>{value || '—'}</span>
    </div>
  );
}

export default function BioStatus({ state }: Props) {
  if (!state || !state.owner_id) {
    return (
      <div className="flex flex-col items-center justify-center h-48 text-on-surface-variant">
        <p className="text-sm">Bio engine not initialized.</p>
        <p className="text-xs mt-1 opacity-60">Send <code className="font-mono">.bio on</code> in Telegram to start.</p>
      </div>
    );
  }

  const updatedAgo = (() => {
    const diff = Date.now() - new Date(state.updated_at).getTime();
    const m = Math.floor(diff / 60000);
    if (m < 1) return 'just now';
    if (m < 60) return `${m}m ago`;
    return `${Math.floor(m / 60)}h ago`;
  })();

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between mb-1">
        <h2 className="text-sm font-semibold text-on-surface-variant uppercase tracking-widest">Bio Engine</h2>
        <span className={`text-xs px-3 py-1 rounded-full font-medium ${
          state.is_active
            ? 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/30'
            : 'bg-surface-variant text-on-surface-variant border border-outline-variant'
        }`}>
          {state.is_active ? 'ACTIVE' : 'INACTIVE'}
        </span>
      </div>

      <div className="bg-surface-container border border-outline-variant rounded-2xl p-5 space-y-4">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <Field label="Template" value={state.template} mono />
          <Field label="Mood" value={state.mood} />
          <Field label="Custom Text" value={state.custom_text} />
          <Field label="Last Updated" value={updatedAgo} />
        </div>

        {state.last_bio && (
          <div className="pt-3 border-t border-outline-variant">
            <p className="text-xs text-on-surface-variant uppercase tracking-widest opacity-60 mb-1.5">Last Rendered Bio</p>
            <div className="bg-surface rounded-xl px-4 py-3 text-sm text-on-surface font-mono border border-outline-variant/50">
              {state.last_bio}
            </div>
          </div>
        )}
      </div>

      <div className="bg-surface-container border border-outline-variant rounded-2xl p-5">
        <p className="text-xs text-on-surface-variant uppercase tracking-widest opacity-60 mb-3">Template Tokens</p>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
          {[
            { token: '{time}', desc: 'Current time (HH:MM)' },
            { token: '{mood}', desc: 'Current mood value' },
            { token: '{text}', desc: 'Custom freeform text' },
          ].map(({ token, desc }) => (
            <div key={token} className="flex flex-col gap-1 p-3 bg-surface rounded-xl border border-outline-variant/50">
              <span className="font-mono text-sm text-primary">{token}</span>
              <span className="text-xs text-on-surface-variant">{desc}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import type { BotLog } from '../lib/api';

interface Props {
  logs: BotLog[];
}

const LEVEL_STYLES: Record<string, string> = {
  INFO:  'text-sky-400 bg-sky-400/10',
  WARN:  'text-amber-400 bg-amber-400/10',
  ERROR: 'text-red-400 bg-red-400/10',
};

function formatTime(iso: string): string {
  return new Date(iso).toLocaleTimeString('en-US', { hour12: false });
}

export default function LogViewer({ logs }: Props) {
  const [filter, setFilter] = useState<'ALL' | 'INFO' | 'WARN' | 'ERROR'>('ALL');

  const filtered = filter === 'ALL' ? logs : logs.filter(l => l.level === filter);

  if (!logs.length) {
    return (
      <div className="flex flex-col items-center justify-center h-48 text-on-surface-variant">
        <p className="text-sm">No logs recorded yet.</p>
      </div>
    );
  }

  const counts = {
    ALL: logs.length,
    INFO: logs.filter(l => l.level === 'INFO').length,
    WARN: logs.filter(l => l.level === 'WARN').length,
    ERROR: logs.filter(l => l.level === 'ERROR').length,
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-sm font-semibold text-on-surface-variant uppercase tracking-widest">Logs</h2>
        <div className="flex gap-1">
          {(['ALL', 'INFO', 'WARN', 'ERROR'] as const).map(lvl => (
            <button
              key={lvl}
              onClick={() => setFilter(lvl)}
              className={`text-xs px-2.5 py-1 rounded-full transition-colors ${
                filter === lvl
                  ? 'bg-primary text-on-primary'
                  : 'text-on-surface-variant hover:bg-surface-variant'
              }`}
            >
              {lvl} {counts[lvl] > 0 && <span className="opacity-70">{counts[lvl]}</span>}
            </button>
          ))}
        </div>
      </div>

      <div className="bg-surface-container border border-outline-variant rounded-2xl overflow-hidden">
        <div className="divide-y divide-outline-variant/50 max-h-[600px] overflow-y-auto">
          {filtered.length === 0 ? (
            <div className="px-5 py-8 text-center text-sm text-on-surface-variant">
              No {filter} logs.
            </div>
          ) : (
            filtered.map(log => (
              <div key={log.id} className="px-5 py-3 flex items-start gap-3 hover:bg-surface-variant/30 transition-colors">
                <span className={`shrink-0 text-xs font-mono px-2 py-0.5 rounded-full mt-0.5 ${LEVEL_STYLES[log.level] || ''}`}>
                  {log.level}
                </span>
                <div className="flex-1 min-w-0">
                  <p className="text-sm text-on-surface leading-snug">{log.message}</p>
                  {log.context && Object.keys(log.context).length > 0 && (
                    <p className="text-xs text-on-surface-variant mt-0.5 font-mono truncate">
                      {JSON.stringify(log.context)}
                    </p>
                  )}
                </div>
                <span className="shrink-0 text-xs text-on-surface-variant font-mono">
                  {formatTime(log.created_at)}
                </span>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

import type { SavedItem } from '../lib/api';

interface Props {
  items: SavedItem[];
  total: number;
}

const TYPE_COLORS: Record<string, string> = {
  Photo: 'text-sky-400 bg-sky-400/10',
  Video: 'text-violet-400 bg-violet-400/10',
  Animation: 'text-amber-400 bg-amber-400/10',
  Audio: 'text-emerald-400 bg-emerald-400/10',
  Voice: 'text-teal-400 bg-teal-400/10',
  Sticker: 'text-pink-400 bg-pink-400/10',
  Document: 'text-slate-400 bg-slate-400/10',
  Unknown: 'text-slate-500 bg-slate-500/10',
};

function fmt(bytes: number | null): string {
  if (!bytes) return '—';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function relativeTime(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return 'just now';
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

export default function SavedItems({ items, total }: Props) {
  if (!items.length) {
    return (
      <div className="flex flex-col items-center justify-center h-48 text-on-surface-variant">
        <p className="text-sm">No saved items yet.</p>
        <p className="text-xs mt-1 opacity-60">Use <code className="font-mono">.save f</code> or <code className="font-mono">.save d</code> in Telegram.</p>
      </div>
    );
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-sm font-semibold text-on-surface-variant uppercase tracking-widest">
          Saved Items
        </h2>
        <span className="text-xs text-on-surface-variant">{total} total</span>
      </div>

      <div className="space-y-2">
        {items.map(item => {
          const typeColor = TYPE_COLORS[item.media_type || 'Unknown'] || TYPE_COLORS.Unknown;
          return (
            <div
              key={item.id}
              className="group bg-surface-container rounded-2xl px-5 py-4 border border-outline-variant hover:border-primary/40 transition-colors"
            >
              <div className="flex items-start justify-between gap-4">
                <div className="flex items-center gap-3 min-w-0">
                  <span className={`shrink-0 text-xs font-mono px-2 py-0.5 rounded-full ${typeColor}`}>
                    {item.media_type || 'Unknown'}
                  </span>
                  <span className="font-mono text-sm font-medium text-primary truncate">
                    {item.save_code}
                  </span>
                  {item.file_name && (
                    <span className="text-xs text-on-surface-variant truncate hidden sm:inline">
                      {item.file_name}
                    </span>
                  )}
                  <span className={`text-xs px-2 py-0.5 rounded-full ${
                    item.save_type === 'deep'
                      ? 'bg-emerald-500/10 text-emerald-400'
                      : 'bg-amber-500/10 text-amber-400'
                  }`}>
                    {item.save_type}
                  </span>
                </div>
                <span className="shrink-0 text-xs text-on-surface-variant">
                  {relativeTime(item.created_at)}
                </span>
              </div>

              <div className="mt-2.5 grid grid-cols-2 sm:grid-cols-4 gap-x-6 gap-y-1 text-xs text-on-surface-variant">
                <div><span className="opacity-50">Sender</span> <span className="text-on-surface">{item.sender_name || '—'}</span></div>
                <div><span className="opacity-50">Chat</span> <span className="font-mono text-on-surface">{item.origin_chat_id ?? '—'}</span></div>
                <div><span className="opacity-50">MIME</span> <span className="text-on-surface">{item.mime_type || '—'}</span></div>
                <div><span className="opacity-50">Size</span> <span className="text-on-surface">{fmt(item.file_size)}</span></div>
              </div>

              {item.file_name && (
                <div className="mt-1.5 text-xs text-on-surface-variant">
                  <span className="opacity-50">File</span> <span className="text-on-surface font-mono">{item.file_name}</span>
                </div>
              )}

              {item.tags && item.tags.length > 0 && (
                <div className="mt-2.5 flex flex-wrap gap-1.5">
                  {item.tags.map(tag => (
                    <span key={tag} className="text-xs text-on-surface-variant bg-surface-variant px-2 py-0.5 rounded-full font-mono">
                      {tag}
                    </span>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

